function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.hopperEntries)) return json.data.hopperEntries;
  if (json && Array.isArray(json.hopperEntries)) return json.hopperEntries;
  return [];
}

const openClaims = $input.all().flatMap(asArray);

if (openClaims.length > 0) {
  return [{ json: { hasOpenClaim: true, entry: openClaims[0] } }];
}

return [{ json: { hasOpenClaim: false } }];

const now = new Date();

// Jonathan's explicit compliance-cadence instruction: 2-3 attempts/day per lead, applying only to
// auto-dialer modes (Power/MultiLine), not Preview, where a human reviews and approves each dial
// individually. Defaulted to the more conservative end of the '2 or 3' range given - tighten or
// loosen by changing this one constant, and treat a missing/unrecognized dialerMode as an
// auto-dialer mode (cap applies) rather than silently exempting it, erring toward compliance
// safety over convenience.
const DAILY_ATTEMPT_CAP = 2;
const dialerMode = $('Request next webhook').item.json.body.dialerMode;
const dailyCapApplies = dialerMode !== 'Preview';

function isSameLocalDay(a, b) {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

// Twenty CRM's list-response shape is unconfirmed, same uncertainty as every REST call in this
// library - tries a direct array first, falls back to a couple of plausible wrapper shapes.
function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.hopperEntries)) return json.data.hopperEntries;
  if (json && Array.isArray(json.hopperEntries)) return json.hopperEntries;
  return [];
}

// Due Callbacks win outright over the shared pool - a rep-promised callback is a commitment,
// not just another queueable record (CRM-OBJECT-MODEL.md's Callback vs. Try-back distinction).
// Not subject to the daily attempt cap - a scheduled callback is invited contact, not a repeated
// unsolicited dial attempt, so it isn't the thing the cap exists to limit.
const dueCallbacks = $('Fetch due callbacks').all().flatMap(asArray)
  .filter((e) => !e.nextEligibleAt || new Date(e.nextEligibleAt) <= now)
  .sort((a, b) => new Date(a.nextEligibleAt || 0) - new Date(b.nextEligibleAt || 0));

if (dueCallbacks.length > 0) {
  return [{ json: { found: true, source: 'callback', entry: dueCallbacks[0] } }];
}

// Shared pool: oldest wave first, then longest-idle within that wave - recycled (Try-back) entries
// with a future nextEligibleAt aren't eligible yet, same recycling window W3.3 computes. Also
// excludes anything already at today's attempt cap when dailyCapApplies.
const poolCandidates = $input.all().flatMap(asArray)
  .filter((e) => !e.nextEligibleAt || new Date(e.nextEligibleAt) <= now)
  .filter((e) => {
    if (!dailyCapApplies) return true;
    const attemptedToday = e.lastAttemptDate && isSameLocalDay(new Date(e.lastAttemptDate), now);
    return !attemptedToday || (e.attemptCountToday || 0) < DAILY_ATTEMPT_CAP;
  })
  .sort((a, b) => {
    if (a.wave !== b.wave) return a.wave - b.wave;
    return new Date(a.lastAttemptDate || 0) - new Date(b.lastAttemptDate || 0);
  });

if (poolCandidates.length > 0) {
  return [{ json: { found: true, source: 'pool', entry: poolCandidates[0] } }];
}

return [{ json: { found: false } }];
